-- Limpiar RouteStops huérfanos PRIMERO (FK StopId -> Stop.Id)
DELETE FROM Route.RouteStop 
WHERE StopId IN (
    'F2000031-0000-4000-8000-000000000031',
    'F2000032-0000-4000-8000-000000000032',
    'F2000033-0000-4000-8000-000000000033',
    'F2000034-0000-4000-8000-000000000034',
    'F2000035-0000-4000-8000-000000000035',
    'F2000036-0000-4000-8000-000000000036'
);

-- Luego limpiar paradas duplicadas
DELETE FROM Route.Stop 
WHERE Id IN (
    'F2000031-0000-4000-8000-000000000031',
    'F2000032-0000-4000-8000-000000000032',
    'F2000033-0000-4000-8000-000000000033',
    'F2000034-0000-4000-8000-000000000034',
    'F2000035-0000-4000-8000-000000000035',
    'F2000036-0000-4000-8000-000000000036'
);